C.source:
static inline uint32_t hw_inc1(uint32_t x) { return x + 1; }
static inline uint32_t hw_dbl(uint32_t x) { return x + x; }
static inline uint32_t hw_chain3(uint32_t x, uint32_t y) { return hw_inc1(hw_dbl(hw_inc1(x))) + y; }

JavaScript.source:
function inc1(x) { return (x + 1) >>> 0; }
function dbl(x) { return (x + x) >>> 0; }
export function chain3(x, y) { return (inc1(dbl(inc1(x))) + y) >>> 0; }

Rust.source:
#[inline] fn inc1(x: u32) -> u32 { x.wrapping_add(1) }
#[inline] fn dbl(x: u32) -> u32 { x.wrapping_add(x) }
#[inline] fn hw_chain3(x: u32, y: u32) -> u32 { inc1(dbl(inc1(x))).wrapping_add(y) }
